package com.greenlink.controller;import com.greenlink.dto.*;import com.greenlink.security.AppUserPrincipal;import com.greenlink.service.DashboardService;import org.bson.types.ObjectId;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController {private final DashboardService s;public DashboardController(DashboardService s){this.s=s;} @GetMapping("/stats") public DashboardStats stats(){return s.stats();} @GetMapping("/provider-stats") public ProviderStats provider(@AuthenticationPrincipal AppUserPrincipal p){return s.provider(new ObjectId(p.getId()));}}
